#include "domain/service_registry.h"

void reload_configuration() {
    AppConfig* new_config = load_config_from_file("path/to/config.ini");
    if (!new_config) {
        log_error("Failed to reload configuration file.");
        return;
    }

    // Assume get_all_services() exists in service_registry
    ServiceRegistration* services = get_all_services();
    for (int i = 0; i < get_service_count(); ++i) {
        if (services[i].reconfigure) {
            services[i].reconfigure(new_config);
        }
    }

    // The ownership of the old global config must be handled correctly
    free_config(get_global_config());
    set_global_config(new_config);
}
```

