#include <pthread.h>

static LogLevel g_current_log_level;
static pthread_mutex_t g_log_level_mutex = PTHREAD_MUTEX_INITIALIZER;

// The new reconfigure function
static void log_store_reconfigure(const AppConfig* new_config) {
    if (!new_config) return;
    LogLevel new_level = new_config->logging.level;

    pthread_mutex_lock(&g_log_level_mutex);
    g_current_log_level = new_level;
    pthread_mutex_unlock(&g_log_level_mutex);

    log_info("Log level updated to %d", new_level);
}

